
const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#090b10\">\n  <meta name=\"description\" content=\"Real English speaking practice with live conversation, useful coaching, and learning memory.\">\n  <meta property=\"og:title\" content=\"Fluent Me\">\n  <meta property=\"og:description\" content=\"Speak. Notice. Say it better.\">\n  <meta property=\"og:image\" content=\"/static/og-v2.png\">\n  <title>Fluent Me — speaking practice</title>\n  <link rel=\"stylesheet\" href=\"/static/live.css\">\n  <script crossorigin src=\"https://unpkg.com/@daily-co/daily-js\"></script>\n</head>\n<body data-screen=\"setup\" data-session-state=\"idle\">\n  <div class=\"app-shell\">\n    <header class=\"app-bar\">\n      <a class=\"brand\" href=\"/\" aria-label=\"Fluent Me home\">\n        <span class=\"brand-glyph\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></span>\n        <span>Fluent Me</span>\n      </a>\n      <nav class=\"app-nav\" aria-label=\"Primary navigation\">\n        <a href=\"#mirror-card\">Voice mirror</a>\n        <a href=\"#report-card\">Learning memory</a>\n      </nav>\n      <div class=\"capability-pill\" id=\"capability-pill\" aria-live=\"polite\">\n        <span></span><b id=\"capability-label\">Getting ready</b>\n      </div>\n    </header>\n\n    <main>\n      <section class=\"setup-screen\" id=\"setup-screen\" aria-labelledby=\"setup-title\">\n        <div class=\"setup-copy\">\n          <p class=\"overline\">Live speaking practice</p>\n          <h1 id=\"setup-title\">What do you want to get better at?</h1>\n          <p>Say a real answer. Get one useful note. Try it again while it is still fresh.</p>\n        </div>\n\n        <div class=\"setup-grid\">\n          <section class=\"prompt-builder\" aria-label=\"Choose a practice goal\">\n            <label for=\"practice-goal\">Today I want to practice</label>\n            <textarea id=\"practice-goal\" rows=\"3\" maxlength=\"240\">Explain a product I built from zero to one</textarea>\n\n            <div class=\"prompt-suggestions\" role=\"group\" aria-label=\"Suggested practice goals\">\n              <button class=\"prompt-chip selected\" type=\"button\" data-focus=\"interview\" data-prompt=\"Explain a product I built from zero to one\">\n                <span>01</span><b>Zero to one</b><small>Explain what you owned and why it mattered</small>\n              </button>\n              <button class=\"prompt-chip\" type=\"button\" data-focus=\"interview\" data-prompt=\"Describe how I understand the AI ecosystem\">\n                <span>02</span><b>AI ecosystem</b><small>Models, infrastructure, products, and distribution</small>\n              </button>\n              <button class=\"prompt-chip\" type=\"button\" data-focus=\"interview\" data-prompt=\"Explain why Tavus is more than a digital face\">\n                <span>03</span><b>Tavus interview</b><small>Perception, turn-taking, memory, and interaction</small>\n              </button>\n              <button class=\"prompt-chip\" type=\"button\" data-focus=\"conversation\" data-prompt=\"Have a natural conversation about what I am building\">\n                <span>04</span><b>Open conversation</b><small>Practice without a script</small>\n              </button>\n            </div>\n          </section>\n\n          <aside class=\"session-card\">\n            <div class=\"session-card-top\">\n              <span class=\"mode-icon\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i><i></i></span>\n              <div><p id=\"mode-kicker\">60-second practice</p><h2 id=\"mode-title\">Ready on this device</h2></div>\n            </div>\n            <ol class=\"session-steps\">\n              <li><span>1</span><div><b>Speak naturally</b><small>Use your microphone or type if speech recognition is unavailable.</small></div></li>\n              <li><span>2</span><div><b>See real evidence</b><small>Your words, pace, fillers, and answer structure—not a made-up score.</small></div></li>\n              <li><span>3</span><div><b>Try it once more</b><small>Carry one specific improvement into the second attempt.</small></div></li>\n            </ol>\n            <label class=\"camera-setting\" id=\"camera-setting\" hidden>\n              <input id=\"camera-enabled\" type=\"checkbox\" checked>\n              <span><b>Use my camera</b><small>Optional. Visible context is never used for grading.</small></span>\n            </label>\n            <button class=\"start-button\" id=\"start-button\" type=\"button\" disabled>\n              <span id=\"start-label\">Preparing practice</span><i aria-hidden=\"true\">→</i>\n            </button>\n            <p class=\"privacy-note\" id=\"privacy-note\"><span aria-hidden=\"true\">●</span> Microphone access starts only after you continue.</p>\n          </aside>\n        </div>\n\n        <section class=\"recent-practice\" id=\"recent-practice\" hidden aria-labelledby=\"recent-title\">\n          <div><p class=\"overline\">Last practice</p><h2 id=\"recent-title\">Pick up where you left off</h2></div>\n          <div class=\"recent-summary\"><span id=\"recent-goal\"></span><b id=\"recent-result\"></b></div>\n          <button id=\"recent-retry\" type=\"button\">Practice again <span>→</span></button>\n        </section>\n      </section>\n\n      <section class=\"practice-screen\" id=\"practice-screen\" hidden aria-label=\"Speaking practice room\">\n        <header class=\"room-bar\">\n          <div class=\"room-goal\"><span>Goal</span><b id=\"room-goal\"></b></div>\n          <div class=\"room-status\"><i></i><span id=\"room-status\">Ready</span><time id=\"room-timer\">00:00</time></div>\n          <button class=\"end-session\" id=\"end-session\" type=\"button\">End</button>\n        </header>\n\n        <div class=\"room-layout\">\n          <section class=\"conversation-stage\" id=\"conversation-stage\">\n            <div class=\"browser-stage\" id=\"browser-stage\">\n              <div class=\"stage-topline\"><span id=\"attempt-label\">Attempt 1 of 2</span><span id=\"stage-mode\">On-device practice</span></div>\n              <div class=\"prompt-display\">\n                <p id=\"stage-kicker\">Your prompt</p>\n                <h2 id=\"stage-prompt\"></h2>\n                <p id=\"stage-instruction\">Take a breath. Start when you are ready.</p>\n              </div>\n              <canvas class=\"voice-canvas\" id=\"voice-canvas\" width=\"1200\" height=\"240\" aria-label=\"Live microphone level\"></canvas>\n              <div class=\"live-words\" id=\"live-words\" aria-live=\"polite\">Your words will appear here as you speak.</div>\n              <div class=\"text-fallback\" id=\"text-fallback\" hidden>\n                <label for=\"fallback-answer\">Speech recognition is unavailable. Type the answer you would say aloud.</label>\n                <textarea id=\"fallback-answer\" rows=\"6\" maxlength=\"2400\" placeholder=\"Type your answer here…\"></textarea>\n              </div>\n              <div class=\"stage-message\" id=\"stage-message\" hidden></div>\n            </div>\n            <div class=\"video-stage\" id=\"video-stage\" hidden></div>\n            <div class=\"caption-strip\" id=\"caption-strip\" hidden><span id=\"caption-speaker\">You</span><p id=\"caption-text\"></p></div>\n          </section>\n\n          <aside class=\"coach-panel\">\n            <div class=\"panel-tabs\" role=\"tablist\" aria-label=\"Practice insights\">\n              <button class=\"panel-tab active\" id=\"coaching-tab\" type=\"button\" role=\"tab\" aria-selected=\"true\" data-panel=\"coaching\">Coaching</button>\n              <button class=\"panel-tab\" id=\"perception-tab\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-panel=\"perception\" disabled>Perception</button>\n            </div>\n\n            <div class=\"panel-content\" id=\"coaching-panel\" role=\"tabpanel\">\n              <section class=\"goal-card\"><span>Your goal</span><p id=\"panel-goal\"></p></section>\n\n              <section class=\"coach-note\" id=\"coach-note\">\n                <div class=\"note-empty\" id=\"note-empty\">\n                  <span class=\"listening-orb\" aria-hidden=\"true\"><i></i></span>\n                  <h3>Your most useful note will appear here.</h3>\n                  <p>We wait until you finish. Nothing interrupts your answer.</p>\n                </div>\n                <div class=\"note-result\" id=\"note-result\" hidden>\n                  <p class=\"panel-eyebrow\">One thing to try</p>\n                  <h3 id=\"note-title\"></h3>\n                  <p id=\"note-body\"></p>\n                  <blockquote id=\"note-target\"></blockquote>\n                  <button class=\"listen-button\" id=\"listen-button\" type=\"button\" hidden><span>▶</span><b id=\"listen-label\">Listen to the rewrite</b></button>\n                </div>\n              </section>\n\n              <section class=\"evidence\" id=\"evidence\" aria-label=\"Answer evidence\">\n                <div><span>Time</span><b id=\"metric-time\">—</b></div>\n                <div><span>Pace</span><b id=\"metric-wpm\">—</b></div>\n                <div><span>Fillers</span><b id=\"metric-fillers\">—</b></div>\n              </section>\n\n              <section class=\"attempt-compare\" id=\"attempt-compare\" hidden>\n                <span>Second attempt</span><h3 id=\"compare-title\"></h3><p id=\"compare-copy\"></p>\n              </section>\n            </div>\n\n            <div class=\"panel-content\" id=\"perception-panel\" role=\"tabpanel\" hidden>\n              <p class=\"perception-intro\">Observations are tentative conversational context. They never affect your language feedback.</p>\n              <section class=\"perception-item\"><span>Voice delivery</span><p id=\"audio-perception\">Waiting for a complete turn.</p></section>\n              <section class=\"perception-item\"><span>Visible context</span><p id=\"visual-perception\">Waiting for camera context.</p></section>\n              <div class=\"perception-footnote\"><i></i><span>Context only · not used in scoring</span></div>\n            </div>\n          </aside>\n        </div>\n\n        <footer class=\"room-controls\">\n          <div class=\"media-controls\">\n            <button class=\"round-control\" id=\"mic-toggle\" type=\"button\" aria-label=\"Mute microphone\" hidden>Mic</button>\n            <button class=\"round-control\" id=\"camera-toggle\" type=\"button\" aria-label=\"Turn camera off\" hidden>Camera</button>\n          </div>\n          <button class=\"record-control\" id=\"record-control\" type=\"button\"><span class=\"record-dot\"></span><b id=\"record-label\">Start answer</b></button>\n          <button class=\"quiet-control\" id=\"transcript-toggle\" type=\"button\">Transcript</button>\n        </footer>\n      </section>\n\n      <section class=\"review-screen\" id=\"review-screen\" hidden aria-labelledby=\"review-title\">\n        <div class=\"review-mark\" aria-hidden=\"true\"><span>✓</span></div>\n        <p class=\"overline\">Practice complete</p>\n        <h1 id=\"review-title\">You said it better the second time.</h1>\n        <p class=\"review-lede\" id=\"review-lede\"></p>\n\n        <div class=\"review-grid\">\n          <section class=\"review-main\">\n            <p class=\"panel-eyebrow\">Carry this forward</p>\n            <h2 id=\"review-note-title\"></h2>\n            <p id=\"review-note-body\"></p>\n            <blockquote id=\"review-target\"></blockquote>\n          </section>\n          <section class=\"review-evidence\">\n            <div><span>Attempts</span><b id=\"review-attempts\">1</b></div>\n            <div><span>Latest pace</span><b id=\"review-wpm\">—</b></div>\n            <div><span>Latest fillers</span><b id=\"review-fillers\">—</b></div>\n            <div><span>Practice time</span><b id=\"review-time\">—</b></div>\n          </section>\n        </div>\n\n        <details class=\"transcript-details\" id=\"transcript-details\">\n          <summary>Review what I said <span>＋</span></summary>\n          <div id=\"review-transcript\"></div>\n        </details>\n\n        <div class=\"review-actions\">\n          <button class=\"start-button compact\" id=\"practice-again\" type=\"button\"><span>Practice this again</span><i>→</i></button>\n          <button class=\"secondary-button\" id=\"new-goal\" type=\"button\">Choose a new goal</button>\n        </div>\n      </section>\n    </main>\n  </div>\n\n  <script src=\"/static/live.js\" defer></script>\n</body>\n</html>\n";
const CSS = ":root {\n  color-scheme: dark;\n  --bg: #090b10;\n  --bg-soft: #0d1016;\n  --panel: #11151c;\n  --panel-high: #161b24;\n  --line: #252b36;\n  --line-soft: #1b2029;\n  --text: #f5f6f8;\n  --muted: #939baa;\n  --quiet: #687180;\n  --violet: #806cff;\n  --violet-bright: #9a8cff;\n  --violet-soft: rgba(128, 108, 255, .13);\n  --mint: #40d9ad;\n  --danger: #ff667a;\n  --shadow: 0 24px 70px rgba(0, 0, 0, .34);\n  --radius: 18px;\n  --sans: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\n\n* { box-sizing: border-box; }\n[hidden] { display: none !important; }\nhtml { background: var(--bg); scroll-behavior: smooth; }\nbody {\n  margin: 0;\n  min-width: 320px;\n  min-height: 100dvh;\n  background:\n    radial-gradient(circle at 75% -20%, rgba(128, 108, 255, .12), transparent 35rem),\n    radial-gradient(circle at -10% 110%, rgba(64, 217, 173, .05), transparent 32rem),\n    var(--bg);\n  color: var(--text);\n  font-family: var(--sans);\n  -webkit-font-smoothing: antialiased;\n}\n\nbutton, textarea, input { font: inherit; }\nbutton, a { -webkit-tap-highlight-color: transparent; }\nbutton { color: inherit; }\na { color: inherit; text-decoration: none; }\nbutton:focus-visible, a:focus-visible, textarea:focus-visible, input:focus-visible {\n  outline: 2px solid var(--violet-bright);\n  outline-offset: 3px;\n}\n\n.app-shell { width: min(1480px, 100%); min-height: 100dvh; margin: 0 auto; padding: 0 42px 48px; }\n.app-bar {\n  height: 82px;\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  align-items: center;\n  border-bottom: 1px solid var(--line-soft);\n}\n.brand { display: inline-flex; width: fit-content; align-items: center; gap: 11px; font-size: 16px; font-weight: 680; letter-spacing: -.02em; }\n.brand-glyph { width: 23px; height: 23px; display: flex; align-items: center; justify-content: center; gap: 2px; }\n.brand-glyph i { display: block; width: 3px; border-radius: 4px; background: linear-gradient(180deg, var(--violet-bright), var(--mint)); }\n.brand-glyph i:nth-child(1) { height: 7px; }\n.brand-glyph i:nth-child(2) { height: 17px; }\n.brand-glyph i:nth-child(3) { height: 12px; }\n.brand-glyph i:nth-child(4) { height: 5px; }\n.app-nav { display: flex; align-items: center; gap: 28px; color: var(--muted); font-size: 13px; }\n.app-nav a { transition: color .18s ease; }\n.app-nav a:hover { color: var(--text); }\n.capability-pill {\n  justify-self: end;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-height: 32px;\n  padding: 0 12px;\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  background: rgba(17, 21, 28, .72);\n  color: var(--muted);\n  font-size: 11px;\n}\n.capability-pill span { width: 6px; height: 6px; border-radius: 50%; background: var(--quiet); box-shadow: 0 0 0 4px rgba(104, 113, 128, .1); }\n.capability-pill b { font-weight: 560; }\n.capability-pill.ready span { background: var(--mint); box-shadow: 0 0 0 4px rgba(64, 217, 173, .1); }\n.capability-pill.ready b { color: #c9f7e9; }\n\nmain { min-width: 0; }\n.setup-screen { padding: clamp(66px, 8vw, 112px) 0 40px; }\n.setup-copy { max-width: 780px; }\n.overline, .panel-eyebrow {\n  margin: 0 0 17px;\n  color: var(--violet-bright);\n  font-size: 11px;\n  font-weight: 720;\n  letter-spacing: .14em;\n  text-transform: uppercase;\n}\n.setup-copy h1 {\n  max-width: 760px;\n  margin: 0;\n  font-size: clamp(44px, 6vw, 76px);\n  line-height: .98;\n  letter-spacing: -.065em;\n  font-weight: 610;\n}\n.setup-copy > p:last-child { max-width: 640px; margin: 24px 0 0; color: var(--muted); font-size: 17px; line-height: 1.65; }\n.setup-grid { display: grid; grid-template-columns: minmax(0, 1.45fr) minmax(340px, .72fr); gap: 26px; margin-top: 58px; align-items: stretch; }\n.prompt-builder, .session-card, .recent-practice {\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  background: rgba(17, 21, 28, .86);\n  box-shadow: var(--shadow);\n}\n.prompt-builder { padding: 28px; }\n.prompt-builder > label { display: block; margin: 0 0 13px; color: var(--muted); font-size: 12px; font-weight: 630; }\n#practice-goal {\n  width: 100%;\n  min-height: 104px;\n  resize: vertical;\n  padding: 17px 18px;\n  border: 1px solid #303745;\n  border-radius: 13px;\n  background: #0b0e13;\n  color: var(--text);\n  font-size: clamp(18px, 2vw, 24px);\n  font-weight: 520;\n  line-height: 1.4;\n  letter-spacing: -.025em;\n  caret-color: var(--violet-bright);\n  transition: border-color .18s ease, box-shadow .18s ease;\n}\n#practice-goal:hover, #practice-goal:focus { border-color: #5f56a5; box-shadow: 0 0 0 4px rgba(128, 108, 255, .08); outline: none; }\n.prompt-suggestions { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 18px; }\n.prompt-chip {\n  min-width: 0;\n  display: grid;\n  grid-template-columns: 25px minmax(0, 1fr);\n  grid-template-rows: auto auto;\n  column-gap: 9px;\n  padding: 15px;\n  text-align: left;\n  border: 1px solid var(--line);\n  border-radius: 12px;\n  background: #0d1016;\n  cursor: pointer;\n  transition: transform .18s ease, border-color .18s ease, background .18s ease;\n}\n.prompt-chip:hover { transform: translateY(-1px); border-color: #474e5c; background: #11151c; }\n.prompt-chip.selected { border-color: rgba(128, 108, 255, .75); background: var(--violet-soft); }\n.prompt-chip > span { grid-row: 1 / 3; color: var(--quiet); font-size: 10px; padding-top: 3px; }\n.prompt-chip b { min-width: 0; color: #e9eaf0; font-size: 13px; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.prompt-chip small { min-width: 0; margin-top: 5px; color: var(--quiet); font-size: 11px; line-height: 1.35; }\n.prompt-chip.selected > span, .prompt-chip.selected b { color: #c4bbff; }\n\n.session-card { display: flex; flex-direction: column; padding: 26px; background: linear-gradient(160deg, rgba(23, 28, 38, .98), rgba(13, 16, 22, .98)); }\n.session-card-top { display: flex; align-items: center; gap: 15px; padding-bottom: 22px; border-bottom: 1px solid var(--line); }\n.session-card-top p { margin: 0 0 5px; color: var(--muted); font-size: 11px; }\n.session-card-top h2 { margin: 0; font-size: 18px; font-weight: 600; letter-spacing: -.03em; }\n.mode-icon { width: 42px; height: 42px; flex: 0 0 auto; display: flex; align-items: center; justify-content: center; gap: 2px; border: 1px solid rgba(128, 108, 255, .3); border-radius: 12px; background: var(--violet-soft); }\n.mode-icon i { width: 2px; border-radius: 3px; background: var(--violet-bright); }\n.mode-icon i:nth-child(1), .mode-icon i:nth-child(5) { height: 8px; opacity: .5; }\n.mode-icon i:nth-child(2), .mode-icon i:nth-child(4) { height: 16px; opacity: .75; }\n.mode-icon i:nth-child(3) { height: 24px; }\n.session-steps { list-style: none; margin: 22px 0 26px; padding: 0; display: grid; gap: 18px; }\n.session-steps li { display: grid; grid-template-columns: 25px 1fr; gap: 10px; }\n.session-steps li > span { width: 21px; height: 21px; display: grid; place-items: center; border: 1px solid var(--line); border-radius: 50%; color: var(--quiet); font-size: 9px; }\n.session-steps b { display: block; margin: 1px 0 4px; font-size: 12px; font-weight: 600; }\n.session-steps small { display: block; color: var(--quiet); font-size: 11px; line-height: 1.45; }\n.camera-setting { display: flex; align-items: center; gap: 12px; margin: auto 0 16px; padding: 13px 14px; border: 1px solid var(--line); border-radius: 11px; background: rgba(9, 11, 16, .55); cursor: pointer; }\n.camera-setting input { width: 16px; height: 16px; accent-color: var(--violet); }\n.camera-setting b, .camera-setting small { display: block; }\n.camera-setting b { font-size: 11px; }\n.camera-setting small { margin-top: 3px; color: var(--quiet); font-size: 9px; }\n.start-button {\n  width: 100%;\n  min-height: 52px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0 18px;\n  border: 0;\n  border-radius: 12px;\n  background: var(--violet);\n  color: white;\n  cursor: pointer;\n  box-shadow: 0 14px 32px rgba(91, 72, 222, .24);\n  transition: transform .18s ease, background .18s ease, opacity .18s ease;\n}\n.start-button:hover:not(:disabled) { transform: translateY(-1px); background: #8d7cff; }\n.start-button:disabled { cursor: wait; opacity: .45; box-shadow: none; }\n.start-button span { font-size: 13px; font-weight: 660; }\n.start-button i { font-size: 20px; font-style: normal; }\n.privacy-note { margin: 13px 0 0; color: var(--quiet); text-align: center; font-size: 9px; }\n.privacy-note span { margin-right: 5px; color: var(--mint); font-size: 7px; }\n\n.recent-practice { margin-top: 20px; padding: 20px 22px; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 26px; box-shadow: none; }\n.recent-practice .overline { margin-bottom: 5px; font-size: 9px; }\n.recent-practice h2 { margin: 0; font-size: 14px; font-weight: 600; }\n.recent-summary { min-width: 0; padding-left: 24px; border-left: 1px solid var(--line); }\n.recent-summary span, .recent-summary b { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.recent-summary span { color: var(--muted); font-size: 12px; }\n.recent-summary b { margin-top: 4px; color: var(--quiet); font-size: 10px; font-weight: 500; }\n.recent-practice button, .secondary-button {\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  background: transparent;\n  padding: 11px 14px;\n  color: #d9dbe2;\n  font-size: 11px;\n  cursor: pointer;\n}\n.recent-practice button span { margin-left: 8px; color: var(--violet-bright); }\n\n/* Practice room */\n.practice-screen { padding: 26px 0 0; min-height: calc(100dvh - 82px); }\n.room-bar { min-height: 52px; display: grid; grid-template-columns: minmax(0, 1fr) auto 56px; align-items: center; gap: 18px; margin-bottom: 14px; }\n.room-goal { min-width: 0; display: flex; align-items: baseline; gap: 10px; }\n.room-goal span { flex: 0 0 auto; color: var(--quiet); font-size: 10px; text-transform: uppercase; letter-spacing: .12em; }\n.room-goal b { min-width: 0; color: #dfe1e7; font-size: 13px; font-weight: 520; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.room-status { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 11px; }\n.room-status i { width: 7px; height: 7px; border-radius: 50%; background: var(--mint); box-shadow: 0 0 0 5px rgba(64, 217, 173, .08); }\n.room-status time { min-width: 38px; color: var(--quiet); font-variant-numeric: tabular-nums; }\n.end-session { justify-self: end; border: 0; background: transparent; color: #d8d9de; padding: 9px; font-size: 11px; cursor: pointer; }\n.end-session:hover { color: var(--danger); }\n.room-layout { display: grid; grid-template-columns: minmax(0, 1fr) 345px; min-height: min(720px, calc(100dvh - 210px)); border: 1px solid var(--line); border-radius: 18px; overflow: hidden; background: #07090d; box-shadow: var(--shadow); }\n.conversation-stage { position: relative; min-width: 0; min-height: 560px; overflow: hidden; background: #080a0e; }\n.conversation-stage::before { content: \"\"; position: absolute; inset: 0; pointer-events: none; background: radial-gradient(circle at 50% 44%, rgba(128, 108, 255, .1), transparent 38%), linear-gradient(180deg, transparent 65%, rgba(0,0,0,.28)); }\n.browser-stage { position: relative; z-index: 1; height: 100%; min-height: inherit; display: flex; flex-direction: column; padding: 22px 30px 32px; }\n.stage-topline { display: flex; justify-content: space-between; color: var(--quiet); font-size: 9px; letter-spacing: .08em; text-transform: uppercase; }\n.prompt-display { width: min(720px, 88%); margin: auto auto 0; text-align: center; }\n.prompt-display > p:first-child { margin: 0 0 14px; color: var(--violet-bright); font-size: 10px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; }\n.prompt-display h2 { margin: 0; font-size: clamp(28px, 4vw, 50px); line-height: 1.08; letter-spacing: -.05em; font-weight: 580; }\n.prompt-display > p:last-child { margin: 17px 0 0; color: var(--muted); font-size: 13px; }\n.voice-canvas { width: min(880px, 95%); height: 104px; margin: 30px auto 0; opacity: .95; }\n.live-words { width: min(820px, 92%); min-height: 54px; margin: 0 auto auto; color: #aab0bb; text-align: center; font-size: 14px; line-height: 1.55; }\n.live-words.active { color: #eceef2; }\n.text-fallback { width: min(720px, 92%); margin: 22px auto auto; }\n.text-fallback label { display: block; margin-bottom: 10px; color: var(--muted); font-size: 11px; }\n.text-fallback textarea { width: 100%; resize: vertical; padding: 15px; border: 1px solid var(--line); border-radius: 12px; background: #0d1016; color: var(--text); line-height: 1.5; }\n.stage-message { width: min(580px, 90%); margin: 28px auto auto; padding: 13px 15px; border: 1px solid rgba(255, 102, 122, .25); border-radius: 10px; background: rgba(255, 102, 122, .07); color: #ffb1bc; text-align: center; font-size: 11px; }\n.video-stage { position: absolute; inset: 0; z-index: 2; background: #050608; }\n.video-stage iframe { display: block; width: 100% !important; height: 100% !important; border: 0 !important; }\n.caption-strip { position: absolute; z-index: 5; left: 50%; bottom: 24px; width: min(760px, calc(100% - 48px)); transform: translateX(-50%); padding: 13px 16px; border: 1px solid rgba(255,255,255,.1); border-radius: 12px; background: rgba(8,10,14,.82); backdrop-filter: blur(14px); }\n.caption-strip span { display: block; margin-bottom: 4px; color: var(--violet-bright); font-size: 9px; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; }\n.caption-strip p { margin: 0; color: white; font-size: 13px; line-height: 1.45; }\n\n.coach-panel { min-width: 0; border-left: 1px solid var(--line); background: var(--panel); }\n.panel-tabs { height: 55px; display: grid; grid-template-columns: 1fr 1fr; padding: 0 16px; border-bottom: 1px solid var(--line); }\n.panel-tab { position: relative; border: 0; background: transparent; color: var(--quiet); font-size: 11px; cursor: pointer; }\n.panel-tab::after { content: \"\"; position: absolute; left: 12px; right: 12px; bottom: -1px; height: 2px; background: transparent; }\n.panel-tab.active { color: var(--text); }\n.panel-tab.active::after { background: var(--violet-bright); }\n.panel-tab:disabled { opacity: .32; cursor: not-allowed; }\n.panel-content { padding: 18px; }\n.goal-card { padding: 15px; border: 1px solid var(--line); border-radius: 12px; background: #0d1016; }\n.goal-card span, .perception-item span { display: block; margin-bottom: 8px; color: var(--quiet); font-size: 9px; font-weight: 650; letter-spacing: .11em; text-transform: uppercase; }\n.goal-card p { margin: 0; color: #d9dce3; font-size: 12px; line-height: 1.5; }\n.coach-note { min-height: 258px; margin-top: 13px; padding: 18px; border: 1px solid var(--line); border-radius: 12px; background: linear-gradient(155deg, rgba(128, 108, 255, .09), rgba(13, 16, 22, .75) 52%); }\n.note-empty { min-height: 220px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }\n.listening-orb { width: 40px; height: 40px; display: grid; place-items: center; margin-bottom: 16px; border: 1px solid rgba(128,108,255,.35); border-radius: 50%; }\n.listening-orb i { width: 8px; height: 8px; border-radius: 50%; background: var(--violet-bright); box-shadow: 0 0 0 7px rgba(128, 108, 255, .08); }\n.note-empty h3 { max-width: 230px; margin: 0; font-size: 15px; line-height: 1.35; font-weight: 580; }\n.note-empty p { max-width: 220px; margin: 9px 0 0; color: var(--quiet); font-size: 10px; line-height: 1.5; }\n.note-result .panel-eyebrow { margin-bottom: 11px; font-size: 9px; }\n.note-result h3 { margin: 0; font-size: 22px; line-height: 1.15; letter-spacing: -.04em; font-weight: 610; }\n.note-result > p:not(.panel-eyebrow) { margin: 12px 0 0; color: var(--muted); font-size: 11px; line-height: 1.55; }\n.note-result blockquote { margin: 16px 0 0; padding: 13px 14px; border-left: 2px solid var(--violet-bright); background: rgba(128,108,255,.08); color: #e9e6ff; font-size: 11px; line-height: 1.5; }\n.listen-button { width: 100%; display: flex; align-items: center; gap: 10px; margin-top: 14px; padding: 11px 12px; border: 1px solid var(--line); border-radius: 10px; background: #0c0f14; color: #d8dbe3; cursor: pointer; }\n.listen-button span { width: 22px; height: 22px; display: grid; place-items: center; border-radius: 50%; background: var(--violet); font-size: 8px; }\n.listen-button b { font-size: 10px; font-weight: 580; }\n.evidence { display: grid; grid-template-columns: repeat(3, 1fr); margin-top: 13px; border: 1px solid var(--line); border-radius: 12px; overflow: hidden; }\n.evidence div { min-width: 0; padding: 12px 10px; background: #0d1016; }\n.evidence div + div { border-left: 1px solid var(--line); }\n.evidence span, .evidence b { display: block; }\n.evidence span { color: var(--quiet); font-size: 8px; text-transform: uppercase; letter-spacing: .08em; }\n.evidence b { margin-top: 6px; font-size: 13px; font-weight: 590; font-variant-numeric: tabular-nums; }\n.attempt-compare { margin-top: 13px; padding: 14px; border: 1px solid rgba(64,217,173,.24); border-radius: 12px; background: rgba(64,217,173,.05); }\n.attempt-compare > span { color: var(--mint); font-size: 8px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }\n.attempt-compare h3 { margin: 7px 0 0; font-size: 14px; font-weight: 600; }\n.attempt-compare p { margin: 6px 0 0; color: var(--muted); font-size: 10px; line-height: 1.45; }\n.perception-intro { margin: 0 0 17px; color: var(--muted); font-size: 11px; line-height: 1.55; }\n.perception-item { padding: 16px; border: 1px solid var(--line); border-radius: 12px; background: #0d1016; }\n.perception-item + .perception-item { margin-top: 10px; }\n.perception-item p { margin: 0; color: #d5d8df; font-size: 12px; line-height: 1.5; }\n.perception-footnote { display: flex; align-items: center; gap: 8px; margin-top: 16px; color: var(--quiet); font-size: 9px; }\n.perception-footnote i { width: 6px; height: 6px; border-radius: 50%; background: var(--mint); }\n\n.room-controls { min-height: 72px; position: relative; display: flex; align-items: center; justify-content: center; }\n.record-control { min-width: 164px; min-height: 44px; display: flex; align-items: center; justify-content: center; gap: 9px; padding: 0 18px; border: 1px solid rgba(128,108,255,.58); border-radius: 999px; background: var(--violet); color: white; cursor: pointer; box-shadow: 0 10px 25px rgba(90,70,220,.2); }\n.record-control:hover { background: #8d7cff; }\n.record-control b { font-size: 11px; font-weight: 650; }\n.record-dot { width: 8px; height: 8px; border-radius: 50%; background: white; }\nbody[data-session-state=\"recording\"] .record-control { border-color: rgba(255,102,122,.5); background: #4f1f2a; box-shadow: 0 10px 25px rgba(255,102,122,.12); }\nbody[data-session-state=\"recording\"] .record-dot { border-radius: 2px; background: var(--danger); }\n.media-controls { position: absolute; left: 0; display: flex; gap: 8px; }\n.round-control, .quiet-control { border: 1px solid var(--line); background: transparent; color: var(--muted); font-size: 10px; cursor: pointer; }\n.round-control { min-width: 58px; height: 34px; border-radius: 999px; }\n.quiet-control { position: absolute; right: 0; padding: 9px 12px; border-radius: 9px; }\n.round-control.off { color: var(--danger); border-color: rgba(255,102,122,.25); }\n\n/* Review */\n.review-screen { width: min(960px, 100%); margin: 0 auto; padding: clamp(70px, 9vw, 120px) 0 60px; }\n.review-mark { width: 48px; height: 48px; display: grid; place-items: center; margin-bottom: 26px; border: 1px solid rgba(64,217,173,.28); border-radius: 14px; background: rgba(64,217,173,.08); color: var(--mint); }\n.review-mark span { font-size: 18px; }\n.review-screen > h1 { max-width: 790px; margin: 0; font-size: clamp(42px, 6vw, 70px); line-height: 1; letter-spacing: -.06em; font-weight: 600; }\n.review-lede { max-width: 670px; margin: 22px 0 0; color: var(--muted); font-size: 16px; line-height: 1.6; }\n.review-grid { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(280px, .7fr); gap: 16px; margin-top: 48px; }\n.review-main, .review-evidence, .transcript-details { border: 1px solid var(--line); border-radius: 16px; background: var(--panel); }\n.review-main { padding: 28px; }\n.review-main .panel-eyebrow { margin-bottom: 12px; }\n.review-main h2 { margin: 0; font-size: 28px; letter-spacing: -.04em; font-weight: 600; }\n.review-main > p:not(.panel-eyebrow) { margin: 13px 0 0; color: var(--muted); font-size: 13px; line-height: 1.6; }\n.review-main blockquote { margin: 22px 0 0; padding: 17px 18px; border-left: 2px solid var(--violet); background: var(--violet-soft); color: #e9e7ff; font-size: 13px; line-height: 1.55; }\n.review-evidence { display: grid; grid-template-columns: 1fr 1fr; overflow: hidden; }\n.review-evidence div { padding: 22px; }\n.review-evidence div:nth-child(even) { border-left: 1px solid var(--line); }\n.review-evidence div:nth-child(n+3) { border-top: 1px solid var(--line); }\n.review-evidence span, .review-evidence b { display: block; }\n.review-evidence span { color: var(--quiet); font-size: 9px; text-transform: uppercase; letter-spacing: .09em; }\n.review-evidence b { margin-top: 9px; font-size: 20px; font-weight: 590; }\n.transcript-details { margin-top: 16px; overflow: hidden; }\n.transcript-details summary { display: flex; justify-content: space-between; padding: 18px 20px; color: #d8dbe1; font-size: 11px; cursor: pointer; list-style: none; }\n.transcript-details summary::-webkit-details-marker { display: none; }\n.transcript-details[open] summary { border-bottom: 1px solid var(--line); }\n#review-transcript { padding: 20px; display: grid; gap: 16px; }\n.transcript-attempt { display: grid; grid-template-columns: 74px minmax(0,1fr); gap: 14px; }\n.transcript-attempt span { color: var(--violet-bright); font-size: 9px; font-weight: 680; text-transform: uppercase; letter-spacing: .08em; }\n.transcript-attempt p { margin: 0; color: var(--muted); font-size: 12px; line-height: 1.55; }\n.review-actions { display: flex; gap: 10px; margin-top: 24px; }\n.start-button.compact { width: 226px; }\n.secondary-button { min-width: 150px; }\n\n@media (max-width: 1050px) {\n  .app-shell { padding-inline: 24px; }\n  .setup-grid { grid-template-columns: minmax(0, 1.1fr) minmax(310px, .8fr); }\n  .prompt-suggestions { grid-template-columns: 1fr; }\n  .room-layout { grid-template-columns: minmax(0, 1fr) 310px; }\n}\n\n@media (max-width: 820px) {\n  .app-bar { grid-template-columns: 1fr auto; }\n  .app-nav { display: none; }\n  .setup-screen { padding-top: 58px; }\n  .setup-grid { grid-template-columns: 1fr; margin-top: 40px; }\n  .prompt-builder { order: 1; }\n  .session-card { order: 2; }\n  .recent-practice { grid-template-columns: 1fr auto; }\n  .recent-summary { grid-column: 1 / -1; grid-row: 2; padding: 14px 0 0; border-left: 0; border-top: 1px solid var(--line); }\n  .room-layout { grid-template-columns: 1fr; min-height: auto; overflow: visible; border: 0; background: transparent; box-shadow: none; }\n  .conversation-stage { min-height: 58dvh; border: 1px solid var(--line); border-radius: 16px; }\n  .coach-panel { margin-top: 12px; border: 1px solid var(--line); border-radius: 16px; overflow: hidden; }\n  .room-controls { padding-bottom: calc(8px + env(safe-area-inset-bottom)); }\n  .review-grid { grid-template-columns: 1fr; }\n}\n\n@media (max-width: 560px) {\n  .app-shell { padding: 0 15px 32px; }\n  .app-bar { height: 66px; }\n  .capability-pill { padding-inline: 9px; }\n  .setup-screen { padding-top: 42px; }\n  .setup-copy h1 { font-size: 43px; }\n  .setup-copy > p:last-child { font-size: 14px; }\n  .setup-grid { margin-top: 32px; }\n  .prompt-builder, .session-card { padding: 18px; }\n  .prompt-suggestions { grid-template-columns: 1fr; }\n  .room-bar { grid-template-columns: minmax(0,1fr) auto; gap: 9px; }\n  .room-status { grid-column: 1 / -1; grid-row: 2; justify-self: start; }\n  .end-session { grid-column: 2; grid-row: 1; }\n  .conversation-stage { min-height: 56dvh; }\n  .browser-stage { padding: 18px 16px 26px; }\n  .prompt-display { width: 96%; }\n  .prompt-display h2 { font-size: 30px; }\n  .voice-canvas { width: 100%; height: 85px; }\n  .room-controls { justify-content: flex-start; }\n  .record-control { margin-left: auto; margin-right: auto; min-width: 150px; }\n  .media-controls { display: none; }\n  .quiet-control { right: 0; padding-inline: 8px; font-size: 9px; }\n  .review-screen { padding-top: 58px; }\n  .review-screen > h1 { font-size: 44px; }\n  .review-grid { margin-top: 36px; }\n  .review-main { padding: 22px; }\n  .review-evidence div { padding: 17px; }\n  .review-actions { flex-direction: column; }\n  .start-button.compact, .secondary-button { width: 100%; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; animation: none !important; }\n}\n";
const JS = "(() => {\n  \"use strict\";\n\n  const $ = id => document.getElementById(id);\n  const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;\n  const STORAGE_KEY = \"fluent-me:recent-practice:v2\";\n  const state = {\n    capability: \"browser\",\n    configured: false,\n    mirrorVoiceReady: false,\n    focus: \"interview\",\n    goal: \"\",\n    sessionState: \"idle\",\n    speakerState: \"none\",\n    feedbackState: \"idle\",\n    attempts: [],\n    transcriptFinal: \"\",\n    transcriptInterim: \"\",\n    recognition: null,\n    mediaStream: null,\n    audioContext: null,\n    analyser: null,\n    drawFrame: null,\n    timerId: null,\n    startedAt: 0,\n    sessionStartedAt: 0,\n    call: null,\n    conversationId: null,\n    joinTimeout: null,\n    seenEvents: new Set(),\n    pendingFeedback: null,\n    latestFeedback: null,\n    currentAudio: null,\n    captionsVisible: true,\n    ending: false,\n  };\n\n  function setText(id, value) {\n    const node = $(id);\n    if (node) node.textContent = value == null ? \"\" : String(value);\n  }\n\n  function setScreen(screen) {\n    document.body.dataset.screen = screen;\n    $(\"setup-screen\").hidden = screen !== \"setup\";\n    $(\"practice-screen\").hidden = screen !== \"practice\";\n    $(\"review-screen\").hidden = screen !== \"review\";\n    window.scrollTo({ top: 0, behavior: \"smooth\" });\n  }\n\n  function setSessionState(next, label) {\n    state.sessionState = next;\n    document.body.dataset.sessionState = next;\n    if (label) setText(\"room-status\", label);\n  }\n\n  function formatTime(seconds) {\n    if (!Number.isFinite(seconds)) return \"—\";\n    const total = Math.max(0, Math.floor(seconds));\n    return `${String(Math.floor(total / 60)).padStart(2, \"0\")}:${String(total % 60).padStart(2, \"0\")}`;\n  }\n\n  async function fetchJSON(url, options = {}) {\n    const response = await fetch(url, {\n      ...options,\n      headers: { \"content-type\": \"application/json\", ...(options.headers || {}) },\n    });\n    let payload = {};\n    try { payload = await response.json(); } catch {}\n    if (!response.ok) {\n      const error = new Error(payload.error || `Request failed (${response.status})`);\n      error.status = response.status;\n      error.reason = payload.reason;\n      throw error;\n    }\n    return payload;\n  }\n\n  function startTimer(kind = \"recording\") {\n    clearInterval(state.timerId);\n    state.startedAt = Date.now();\n    if (!state.sessionStartedAt) state.sessionStartedAt = state.startedAt;\n    const tick = () => {\n      const elapsed = (Date.now() - (kind === \"session\" ? state.sessionStartedAt : state.startedAt)) / 1000;\n      setText(\"room-timer\", formatTime(elapsed));\n      if (kind === \"recording\" && elapsed >= 60 && state.sessionState === \"recording\") finishBrowserAnswer();\n    };\n    tick();\n    state.timerId = setInterval(tick, 250);\n  }\n\n  function stopTimer() {\n    clearInterval(state.timerId);\n    state.timerId = null;\n  }\n\n  function currentGoal() {\n    return $(\"practice-goal\").value.trim().replace(/\\s+/g, \" \").slice(0, 240) || \"Have a natural conversation in English\";\n  }\n\n  function selectPrompt(button) {\n    document.querySelectorAll(\".prompt-chip\").forEach(chip => chip.classList.toggle(\"selected\", chip === button));\n    state.focus = button.dataset.focus || \"conversation\";\n    $(\"practice-goal\").value = button.dataset.prompt || \"\";\n  }\n\n  function updateCapabilityUI() {\n    const live = state.configured;\n    state.capability = live ? \"tavus\" : \"browser\";\n    $(\"capability-pill\").classList.add(\"ready\");\n    setText(\"capability-label\", live ? \"Live video ready\" : \"Speaking practice ready\");\n    setText(\"mode-kicker\", live ? \"Live video conversation\" : \"60-second practice\");\n    setText(\"mode-title\", live ? \"Private coach ready\" : \"Ready on this device\");\n    setText(\"start-label\", live ? \"Start live conversation\" : \"Start speaking practice\");\n    setText(\"privacy-note\", live\n      ? \"● Microphone required · camera optional · private room\"\n      : \"● Microphone access starts only after you continue.\");\n    $(\"camera-setting\").hidden = !live;\n    $(\"start-button\").disabled = false;\n  }\n\n  function readRecent() {\n    try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || \"null\"); } catch { return null; }\n  }\n\n  function renderRecent() {\n    const recent = readRecent();\n    if (!recent?.goal || !Array.isArray(recent.attempts) || !recent.attempts.length) return;\n    $(\"recent-practice\").hidden = false;\n    setText(\"recent-goal\", recent.goal);\n    const latest = recent.attempts.at(-1);\n    const evidence = [latest.words ? `${latest.words} words` : null,\n      Number.isFinite(latest.wpm) ? `${latest.wpm} wpm` : null,\n      Number.isFinite(latest.fillers) ? `${latest.fillers} fillers` : null].filter(Boolean).join(\" · \");\n    setText(\"recent-result\", evidence || \"Saved on this device\");\n    $(\"recent-retry\").onclick = () => {\n      $(\"practice-goal\").value = recent.goal;\n      state.focus = recent.focus || \"interview\";\n      startPractice();\n    };\n  }\n\n  async function boot() {\n    renderRecent();\n    try {\n      const status = await fetchJSON(\"/api/tavus/status\", { headers: {} });\n      state.configured = Boolean(status.configured);\n      state.mirrorVoiceReady = Boolean(status.mirror_voice_ready);\n    } catch {\n      state.configured = false;\n    }\n    updateCapabilityUI();\n    drawIdleWave();\n  }\n\n  function resetRoom(goal) {\n    state.goal = goal;\n    state.attempts = [];\n    state.transcriptFinal = \"\";\n    state.transcriptInterim = \"\";\n    state.pendingFeedback = null;\n    state.latestFeedback = null;\n    state.feedbackState = \"idle\";\n    state.seenEvents.clear();\n    state.sessionStartedAt = 0;\n    setText(\"room-goal\", goal);\n    setText(\"panel-goal\", goal);\n    setText(\"stage-prompt\", goal);\n    setText(\"room-timer\", \"00:00\");\n    setText(\"metric-time\", \"—\");\n    setText(\"metric-wpm\", \"—\");\n    setText(\"metric-fillers\", \"—\");\n    $(\"note-empty\").hidden = false;\n    $(\"note-result\").hidden = true;\n    $(\"attempt-compare\").hidden = true;\n    $(\"stage-message\").hidden = true;\n    $(\"text-fallback\").hidden = true;\n    $(\"caption-strip\").hidden = true;\n    setText(\"live-words\", \"Your words will appear here as you speak.\");\n    $(\"live-words\").classList.remove(\"active\");\n  }\n\n  function startPractice() {\n    const goal = currentGoal();\n    resetRoom(goal);\n    setScreen(\"practice\");\n    if (state.capability === \"tavus\") startTavusPractice();\n    else startBrowserPractice();\n  }\n\n  function startBrowserPractice() {\n    $(\"browser-stage\").hidden = false;\n    $(\"video-stage\").hidden = true;\n    $(\"record-control\").hidden = false;\n    $(\"mic-toggle\").hidden = true;\n    $(\"camera-toggle\").hidden = true;\n    $(\"perception-tab\").disabled = true;\n    $(\"evidence\").hidden = false;\n    setText(\"stage-mode\", Recognition ? \"Microphone practice\" : \"Text fallback\");\n    prepareBrowserAttempt();\n  }\n\n  function prepareBrowserAttempt() {\n    const attempt = state.attempts.length + 1;\n    setSessionState(\"ready\", \"Ready to speak\");\n    setText(\"attempt-label\", `Attempt ${attempt} of 2`);\n    setText(\"stage-kicker\", attempt === 1 ? \"Your prompt\" : \"Try the same answer again\");\n    setText(\"stage-instruction\", attempt === 1\n      ? \"Take a breath. Start when you are ready.\"\n      : \"Keep the useful parts. Make just the one change in your coaching note.\");\n    setText(\"record-label\", \"Start answer\");\n    $(\"record-control\").disabled = false;\n    $(\"text-fallback\").hidden = true;\n    $(\"stage-message\").hidden = true;\n    setText(\"live-words\", \"Your words will appear here as you speak.\");\n    $(\"live-words\").classList.remove(\"active\");\n    drawIdleWave();\n  }\n\n  function cleanTranscript(value) {\n    return String(value || \"\").replace(/\\s+/g, \" \").replace(/\\s+([,.!?])/g, \"$1\").trim();\n  }\n\n  async function ensureMicrophone() {\n    const active = state.mediaStream?.getAudioTracks().some(track => track.readyState === \"live\");\n    if (active) return state.mediaStream;\n    state.mediaStream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true }, video: false });\n    return state.mediaStream;\n  }\n\n  function setupRecognition() {\n    if (!Recognition) return null;\n    const recognition = new Recognition();\n    recognition.lang = \"en-US\";\n    recognition.continuous = true;\n    recognition.interimResults = true;\n    recognition.maxAlternatives = 1;\n    recognition.onresult = event => {\n      let interim = \"\";\n      for (let index = event.resultIndex; index < event.results.length; index += 1) {\n        const words = event.results[index][0]?.transcript || \"\";\n        if (event.results[index].isFinal) state.transcriptFinal += `${words} `;\n        else interim += words;\n      }\n      state.transcriptInterim = interim;\n      const visible = cleanTranscript(`${state.transcriptFinal} ${interim}`);\n      setText(\"live-words\", visible || \"Listening…\");\n      $(\"live-words\").classList.toggle(\"active\", Boolean(visible));\n    };\n    recognition.onerror = event => {\n      if ([\"not-allowed\", \"service-not-allowed\"].includes(event.error)) switchToTextFallback(\"Microphone transcription was blocked. You can still type the answer you would give.\");\n    };\n    recognition.onend = () => {\n      if (state.sessionState === \"recording\" && !state.ending) {\n        try { recognition.start(); } catch {}\n      }\n    };\n    return recognition;\n  }\n\n  async function beginBrowserAnswer() {\n    setSessionState(\"permission\", \"Opening microphone\");\n    setText(\"record-label\", \"Allow microphone\");\n    state.transcriptFinal = \"\";\n    state.transcriptInterim = \"\";\n    try {\n      await ensureMicrophone();\n    } catch {\n      switchToTextFallback(\"Microphone access is unavailable. Type the answer you would say aloud.\");\n      return;\n    }\n    if (!Recognition) {\n      switchToTextFallback(\"This browser cannot create a live transcript. Type the answer you would say aloud.\");\n      return;\n    }\n    state.recognition = setupRecognition();\n    setSessionState(\"recording\", \"Listening\");\n    setText(\"record-label\", \"Finish answer\");\n    setText(\"stage-instruction\", \"Speak naturally. Finish when your answer feels complete.\");\n    setText(\"live-words\", \"Listening…\");\n    startTimer(\"recording\");\n    startLiveWave();\n    try { state.recognition.start(); } catch { switchToTextFallback(\"Speech transcription did not start. Type the answer you would say aloud.\"); }\n  }\n\n  function switchToTextFallback(message) {\n    stopRecognitionAndMedia();\n    setSessionState(\"text\", \"Text fallback\");\n    setText(\"stage-instruction\", message);\n    $(\"text-fallback\").hidden = false;\n    $(\"fallback-answer\").value = cleanTranscript(`${state.transcriptFinal} ${state.transcriptInterim}`);\n    $(\"fallback-answer\").focus();\n    setText(\"record-label\", \"Analyze answer\");\n    drawIdleWave();\n  }\n\n  function stopRecognitionAndMedia() {\n    if (state.recognition) {\n      state.recognition.onend = null;\n      try { state.recognition.stop(); } catch {}\n      state.recognition = null;\n    }\n    if (state.mediaStream) {\n      state.mediaStream.getTracks().forEach(track => track.stop());\n      state.mediaStream = null;\n    }\n    if (state.audioContext) {\n      state.audioContext.close().catch(() => {});\n      state.audioContext = null;\n      state.analyser = null;\n    }\n    cancelAnimationFrame(state.drawFrame);\n    state.drawFrame = null;\n  }\n\n  function finishBrowserAnswer() {\n    if (state.sessionState !== \"recording\") return;\n    const duration = Math.max(1, (Date.now() - state.startedAt) / 1000);\n    const transcript = cleanTranscript(`${state.transcriptFinal} ${state.transcriptInterim}`);\n    state.ending = true;\n    stopTimer();\n    stopRecognitionAndMedia();\n    state.ending = false;\n    if (transcript.split(/\\s+/).filter(Boolean).length < 3) {\n      switchToTextFallback(\"We did not catch enough words to analyze. Add the answer below, then continue.\");\n      return;\n    }\n    completeBrowserAttempt(transcript, duration, \"speech\");\n  }\n\n  function analyzeTypedAnswer() {\n    const transcript = cleanTranscript($(\"fallback-answer\").value);\n    if (transcript.split(/\\s+/).filter(Boolean).length < 3) {\n      $(\"stage-message\").hidden = false;\n      setText(\"stage-message\", \"Add at least one complete sentence so the coaching note has something real to use.\");\n      return;\n    }\n    $(\"stage-message\").hidden = true;\n    completeBrowserAttempt(transcript, null, \"typed\");\n  }\n\n  function countMatches(text, pattern) {\n    return (text.match(pattern) || []).length;\n  }\n\n  function analyzeEvidence(transcript, duration, source) {\n    const words = transcript.match(/[A-Za-z0-9%'-]+/g) || [];\n    const lower = transcript.toLowerCase();\n    const fillers = countMatches(lower, /\\b(?:um+|uh+|you know|basically|actually|kind of|sort of|i mean)\\b/g);\n    const wpm = Number.isFinite(duration) && duration > 4 ? Math.round(words.length / duration * 60) : null;\n    const ownership = /\\bi\\s+(?:built|created|designed|led|decided|launched|implemented|started|owned|tested|changed|shipped)\\b/i.test(transcript);\n    const outcome = /\\b(?:result|impact|outcome|increased|reduced|improved|grew|saved|adoption|users?|revenue|latency|accuracy|conversion)\\b|\\d+(?:\\.\\d+)?\\s*%/i.test(transcript);\n    const reasoning = /\\b(?:because|so that|which meant|therefore|in order to|the reason)\\b/i.test(transcript);\n    const stackSignals = [\"model\", \"data\", \"infrastructure\", \"application\", \"product\", \"distribution\", \"workflow\", \"agent\", \"interface\"].filter(term => lower.includes(term)).length;\n    const tavusSignals = [\"perception\", \"turn\", \"memory\", \"face\", \"video\", \"voice\", \"latency\", \"interaction\", \"raven\", \"sparrow\"].filter(term => lower.includes(term)).length;\n    return { transcript, source, words: words.length, duration, wpm, fillers, ownership, outcome, reasoning, stackSignals, tavusSignals,\n      structure: Number(ownership) + Number(outcome) + Number(reasoning) };\n  }\n\n  function coachingFor(evidence) {\n    const goal = state.goal.toLowerCase();\n    if (evidence.words < 28) return {\n      title: \"Add one concrete decision\",\n      body: \"The answer is still an outline. Name the problem, one decision you personally made, and what happened next.\",\n      target: \"Try again: problem → your decision → result.\",\n    };\n    if (evidence.fillers >= 4 || evidence.fillers / Math.max(1, evidence.words) > .045) return {\n      title: \"Trade fillers for one pause\",\n      body: `We heard ${evidence.fillers} filler${evidence.fillers === 1 ? \"\" : \"s\"}. A short silent pause will make the same ideas sound more deliberate.`,\n      target: \"Try again: pause before the key decision instead of filling the space.\",\n    };\n    if (Number.isFinite(evidence.wpm) && evidence.wpm > 175) return {\n      title: \"Give the important sentence room\",\n      body: `Your pace was ${evidence.wpm} words per minute. Slow down at the decision and the outcome so they do not disappear inside the story.`,\n      target: \"Try again: one beat before the decision, one beat before the result.\",\n    };\n    if (goal.includes(\"ai ecosystem\") && evidence.stackSignals < 3) return {\n      title: \"Show how the layers connect\",\n      body: \"Make the ecosystem visible: foundation models and data become infrastructure, products, workflows, and distribution.\",\n      target: \"Try again: model layer → infrastructure → application → distribution.\",\n    };\n    if (goal.includes(\"tavus\") && evidence.tavusSignals < 3) return {\n      title: \"Go beyond the face\",\n      body: \"Separate the visual output from the system underneath: perception, conversational turn-taking, reasoning, voice, and memory.\",\n      target: \"Try again: the face is the interface; the product is the real-time interaction system.\",\n    };\n    if (!evidence.ownership) return {\n      title: \"Make your ownership unmistakable\",\n      body: \"The story has context, but your decision is hard to locate. Use a direct sentence beginning with “I decided,” “I built,” or “I changed.”\",\n      target: \"Try again: put your most important “I” sentence near the beginning.\",\n    };\n    if (!evidence.outcome) return {\n      title: \"Land the result\",\n      body: \"You explained the work. Finish with what changed—adoption, time saved, quality, learning, or the next decision it unlocked.\",\n      target: \"Try again: end with one concrete outcome.\",\n    };\n    if (!evidence.reasoning) return {\n      title: \"Expose the reasoning\",\n      body: \"The actions are clear. Add one sentence explaining why that choice was better than the alternatives.\",\n      target: \"Try again: add “I chose this because…” before the outcome.\",\n    };\n    return {\n      title: \"Lead with the outcome\",\n      body: \"The answer already has ownership, reasoning, and a result. Make it sharper by putting the result first, then explain how you got there.\",\n      target: \"Try again: outcome first → decision → evidence.\",\n    };\n  }\n\n  function completeBrowserAttempt(transcript, duration, source) {\n    const evidence = analyzeEvidence(transcript, duration, source);\n    const coaching = coachingFor(evidence);\n    const attempt = { ...evidence, coaching };\n    state.attempts.push(attempt);\n    state.feedbackState = \"ready\";\n    setSessionState(\"feedback\", \"Coaching ready\");\n    renderAttempt(attempt);\n    if (state.attempts.length > 1) renderComparison(state.attempts[0], attempt);\n    setText(\"record-label\", state.attempts.length < 2 ? \"Try it again\" : \"Finish practice\");\n    setText(\"stage-kicker\", \"Answer captured\");\n    setText(\"stage-instruction\", state.attempts.length < 2\n      ? \"Keep the answer. Change only the one thing in your coaching note.\"\n      : \"Two real attempts are ready to compare.\");\n    setText(\"live-words\", transcript);\n    $(\"live-words\").classList.add(\"active\");\n    $(\"text-fallback\").hidden = true;\n    drawIdleWave();\n  }\n\n  function renderAttempt(attempt) {\n    $(\"note-empty\").hidden = true;\n    $(\"note-result\").hidden = false;\n    setText(\"note-title\", attempt.coaching.title);\n    setText(\"note-body\", attempt.coaching.body);\n    setText(\"note-target\", attempt.coaching.target);\n    setText(\"metric-time\", Number.isFinite(attempt.duration) ? formatTime(attempt.duration) : \"typed\");\n    setText(\"metric-wpm\", Number.isFinite(attempt.wpm) ? `${attempt.wpm}` : \"—\");\n    setText(\"metric-fillers\", attempt.fillers);\n    $(\"listen-button\").hidden = true;\n  }\n\n  function renderComparison(first, second) {\n    const gains = [];\n    if (second.structure > first.structure) gains.push(\"clearer structure\");\n    if (second.fillers < first.fillers) gains.push(\"fewer fillers\");\n    if (Number.isFinite(first.wpm) && Number.isFinite(second.wpm) && Math.abs(second.wpm - 140) < Math.abs(first.wpm - 140)) gains.push(\"steadier pace\");\n    $(\"attempt-compare\").hidden = false;\n    setText(\"compare-title\", gains.length ? `Improved: ${gains.join(\" · \")}` : \"A more deliberate second pass\");\n    setText(\"compare-copy\", gains.length\n      ? \"The comparison uses your two actual attempts on this device.\"\n      : \"The evidence stayed similar. Keep the coaching target and make the change more explicit next time.\");\n  }\n\n  function handleRecordControl() {\n    if (state.capability === \"tavus\") return;\n    if ([\"ready\", \"idle\"].includes(state.sessionState)) beginBrowserAnswer();\n    else if (state.sessionState === \"recording\") finishBrowserAnswer();\n    else if (state.sessionState === \"text\") analyzeTypedAnswer();\n    else if (state.sessionState === \"feedback\" && state.attempts.length < 2) prepareBrowserAttempt();\n    else if (state.sessionState === \"feedback\") finishBrowserSession();\n  }\n\n  function comparisonSummary() {\n    if (state.attempts.length < 2) return \"One complete attempt is saved on this device.\";\n    const [first, second] = state.attempts;\n    const changes = [];\n    if (second.fillers < first.fillers) changes.push(`${first.fillers - second.fillers} fewer filler${first.fillers - second.fillers === 1 ? \"\" : \"s\"}`);\n    if (second.structure > first.structure) changes.push(\"a clearer answer structure\");\n    if (Number.isFinite(first.wpm) && Number.isFinite(second.wpm)) changes.push(`pace moved from ${first.wpm} to ${second.wpm} wpm`);\n    return changes.length ? `Your second attempt had ${changes.join(\" and \")}.` : \"You completed two real attempts. Keep the same coaching target for the next session.\";\n  }\n\n  function finishBrowserSession() {\n    stopTimer();\n    stopRecognitionAndMedia();\n    if (!state.attempts.length) {\n      resetToSetup();\n      return;\n    }\n    const latest = state.attempts.at(-1);\n    try {\n      localStorage.setItem(STORAGE_KEY, JSON.stringify({\n        goal: state.goal, focus: state.focus, createdAt: new Date().toISOString(),\n        attempts: state.attempts.map(({ transcript, source, words, duration, wpm, fillers, structure }) => ({ transcript, source, words, duration, wpm, fillers, structure })),\n        coaching: latest.coaching,\n      }));\n    } catch {}\n    renderReview(latest, comparisonSummary());\n  }\n\n  function renderReview(latest, summary, report = null) {\n    setScreen(\"review\");\n    const second = state.attempts.length > 1;\n    setText(\"review-title\", second ? \"You gave the answer a stronger second pass.\" : \"You finished a real speaking attempt.\");\n    setText(\"review-lede\", report?.summary || summary || `You practiced: ${state.goal}`);\n    const coaching = latest?.coaching || state.pendingFeedback || {\n      title: \"Keep one clear through-line\", body: \"Lead with the point, explain your decision, and finish with what changed.\", target: \"Outcome → decision → evidence.\",\n    };\n    setText(\"review-note-title\", coaching.title || \"One thing to carry forward\");\n    setText(\"review-note-body\", coaching.body || report?.best_moment || \"Your learning memory is being updated.\");\n    setText(\"review-target\", coaching.target || report?.best_moment || state.goal);\n    setText(\"review-attempts\", state.attempts.length || report?.turns || 1);\n    setText(\"review-wpm\", Number.isFinite(latest?.wpm) ? `${latest.wpm} wpm` : \"—\");\n    setText(\"review-fillers\", Number.isFinite(latest?.fillers) ? latest.fillers : \"—\");\n    const total = state.attempts.reduce((sum, item) => sum + (item.duration || 0), 0);\n    setText(\"review-time\", total ? formatTime(total) : formatTime((Date.now() - state.sessionStartedAt) / 1000));\n    const transcriptRoot = $(\"review-transcript\");\n    transcriptRoot.replaceChildren();\n    state.attempts.forEach((attempt, index) => {\n      const row = document.createElement(\"article\");\n      row.className = \"transcript-attempt\";\n      const label = document.createElement(\"span\");\n      label.textContent = `Attempt ${index + 1}`;\n      const copy = document.createElement(\"p\");\n      copy.textContent = attempt.transcript || \"Transcript unavailable\";\n      row.append(label, copy);\n      transcriptRoot.append(row);\n    });\n  }\n\n  function resetToSetup(keepGoal = false) {\n    stopTimer();\n    stopRecognitionAndMedia();\n    destroyCall();\n    state.conversationId = null;\n    state.sessionStartedAt = 0;\n    state.ending = false;\n    if (!keepGoal) {\n      state.goal = \"\";\n      state.attempts = [];\n    }\n    setScreen(\"setup\");\n    renderRecent();\n  }\n\n  /* Tavus live conversation */\n  function normalizeRole(role) {\n    if (role === \"user\") return \"user\";\n    if ([\"pal\", \"replica\", \"assistant\"].includes(role)) return \"coach\";\n    return null;\n  }\n\n  function eventKey(message) {\n    return [message.event_type, message.seq ?? \"\", message.inference_id ?? \"\", normalizeRole(message.properties?.role) ?? \"\"].join(\":\");\n  }\n\n  function normalizeMessage(event) {\n    const candidate = event?.data || event;\n    if (typeof candidate === \"string\") {\n      try { return JSON.parse(candidate); } catch { return {}; }\n    }\n    return candidate && typeof candidate === \"object\" ? candidate : {};\n  }\n\n  async function startTavusPractice() {\n    $(\"browser-stage\").hidden = false;\n    $(\"video-stage\").hidden = true;\n    $(\"record-control\").hidden = true;\n    $(\"mic-toggle\").hidden = false;\n    $(\"camera-toggle\").hidden = false;\n    $(\"perception-tab\").disabled = false;\n    $(\"evidence\").hidden = true;\n    setText(\"attempt-label\", \"Private video room\");\n    setText(\"stage-mode\", \"Live conversation\");\n    setText(\"stage-kicker\", \"Opening your room\");\n    setText(\"stage-instruction\", \"Creating room → joining media → waiting for the conversation partner\");\n    setSessionState(\"creating\", \"Creating private room\");\n    if (!window.Daily?.createFrame) {\n      state.capability = \"browser\";\n      setText(\"stage-message\", \"Live video could not load. Continuing with speaking practice on this device.\");\n      $(\"stage-message\").hidden = false;\n      startBrowserPractice();\n      return;\n    }\n    try {\n      const room = await fetchJSON(\"/api/tavus/conversations\", {\n        method: \"POST\",\n        body: JSON.stringify({ focus: state.focus, topic: state.goal }),\n      });\n      state.conversationId = room.conversation_id;\n      sessionStorage.setItem(\"fluent-me:active-conversation\", state.conversationId);\n      setSessionState(\"joining\", \"Joining media\");\n      $(\"video-stage\").hidden = false;\n      const call = window.Daily.createFrame($(\"video-stage\"), {\n        showLeaveButton: false,\n        showFullscreenButton: true,\n        activeSpeakerMode: true,\n        iframeStyle: { width: \"100%\", height: \"100%\", border: \"0\" },\n      });\n      state.call = call;\n      registerCallHandlers(call);\n      await call.join({ url: room.conversation_url, token: room.meeting_token, startVideoOff: !$(\"camera-enabled\").checked });\n      setSessionState(\"waiting\", \"Waiting for coach\");\n      state.joinTimeout = setTimeout(() => {\n        if (state.sessionState === \"waiting\") failLive(\"The coach did not join in time. You can retry or continue with on-device speaking practice.\");\n      }, 20000);\n      const participants = call.participants?.() || {};\n      if (Object.values(participants).some(participant => !participant.local)) activateLive();\n    } catch (error) {\n      await failLive(error.message || \"We could not open the conversation.\");\n    }\n  }\n\n  function registerCallHandlers(call) {\n    call.on(\"app-message\", handleAppMessage);\n    call.on(\"participant-joined\", event => { if (event?.participant && !event.participant.local) activateLive(); });\n    call.on(\"joined-meeting\", () => setSessionState(\"waiting\", \"Waiting for coach\"));\n    call.on(\"left-meeting\", () => { if (!state.ending && state.sessionState === \"live\") endLiveSession(); });\n    call.on(\"error\", event => failLive(event?.errorMsg || \"The live room lost its connection.\"));\n  }\n\n  function activateLive() {\n    clearTimeout(state.joinTimeout);\n    state.joinTimeout = null;\n    $(\"browser-stage\").hidden = true;\n    $(\"video-stage\").hidden = false;\n    state.sessionStartedAt = Date.now();\n    setSessionState(\"live\", \"Your turn\");\n    startTimer(\"session\");\n  }\n\n  async function failLive(message) {\n    clearTimeout(state.joinTimeout);\n    setSessionState(\"error\", \"Connection unavailable\");\n    await cleanupRemoteRoom();\n    state.capability = \"browser\";\n    $(\"browser-stage\").hidden = false;\n    $(\"video-stage\").hidden = true;\n    startBrowserPractice();\n    $(\"stage-message\").hidden = false;\n    setText(\"stage-message\", `${message} Continuing with speaking practice on this device.`);\n  }\n\n  function handleAppMessage(event) {\n    const message = normalizeMessage(event);\n    if (!message.event_type || (message.conversation_id && message.conversation_id !== state.conversationId)) return;\n    const key = eventKey(message);\n    if (state.seenEvents.has(key)) return;\n    state.seenEvents.add(key);\n    const props = message.properties || {};\n    const role = normalizeRole(props.role);\n    if (!role) return;\n    if (message.event_type === \"conversation.started_speaking\") {\n      state.speakerState = role;\n      setSessionState(\"live\", role === \"user\" ? \"Listening\" : \"Coach is speaking\");\n      return;\n    }\n    if (message.event_type === \"conversation.stopped_speaking\") {\n      state.speakerState = \"none\";\n      setSessionState(\"live\", role === \"coach\" ? \"Your turn\" : \"Thinking\");\n      if (role === \"coach\" && state.pendingFeedback) {\n        renderLiveFeedback(state.pendingFeedback);\n        state.pendingFeedback = null;\n      }\n      return;\n    }\n    if (message.event_type !== \"conversation.utterance\") return;\n    const speech = cleanTranscript(props.speech);\n    if (!speech) return;\n    showCaption(role, speech);\n    if (role === \"user\") analyzeLiveTurn(message);\n    else sendCoachEvent(message);\n  }\n\n  function showCaption(role, speech) {\n    $(\"caption-strip\").hidden = !state.captionsVisible;\n    setText(\"caption-speaker\", role === \"user\" ? \"You\" : \"Coach\");\n    setText(\"caption-text\", speech);\n  }\n\n  async function sendCoachEvent(message) {\n    try {\n      await fetchJSON(`/api/tavus/conversations/${encodeURIComponent(state.conversationId)}/events`, {\n        method: \"POST\", body: JSON.stringify(message),\n      });\n    } catch {}\n  }\n\n  async function analyzeLiveTurn(message) {\n    const props = message.properties || {};\n    const speech = cleanTranscript(props.speech);\n    if (props.user_audio_analysis) setText(\"audio-perception\", props.user_audio_analysis);\n    if (props.user_visual_analysis) setText(\"visual-perception\", props.user_visual_analysis);\n    setSessionState(\"live\", \"Reviewing your answer\");\n    try {\n      const result = await fetchJSON(`/api/tavus/conversations/${encodeURIComponent(state.conversationId)}/turn`, {\n        method: \"POST\",\n        body: JSON.stringify({\n          speech,\n          seq: message.seq,\n          inference_id: message.inference_id,\n          turn_idx: message.turn_idx,\n          audio_analysis: props.user_audio_analysis || \"\",\n          visual_analysis: props.user_visual_analysis || \"\",\n        }),\n      });\n      if (result.status === \"processing\") return;\n      const feedback = {\n        title: result.errors?.[0]?.label || result.errors?.[0]?.pattern?.replaceAll(\"-\", \" \") || \"A more natural version\",\n        body: result.errors?.[0]?.explain || \"Keep the meaning; make the phrasing easier to follow.\",\n        target: result.mirror_text || result.recast || result.native || speech,\n        audio: result.mirror_audio,\n        ownVoice: result.mirror_own_voice,\n      };\n      state.attempts.push({ transcript: speech, coaching: feedback, duration: null, wpm: null, fillers: null });\n      if (state.speakerState === \"coach\") state.pendingFeedback = feedback;\n      else renderLiveFeedback(feedback);\n    } catch {\n      setSessionState(\"live\", \"Your turn\");\n    }\n  }\n\n  function renderLiveFeedback(feedback) {\n    $(\"note-empty\").hidden = true;\n    $(\"note-result\").hidden = false;\n    setText(\"note-title\", feedback.title);\n    setText(\"note-body\", feedback.body);\n    setText(\"note-target\", feedback.target);\n    state.latestFeedback = feedback;\n    $(\"listen-button\").hidden = !feedback.audio;\n    setText(\"listen-label\", feedback.ownVoice ? \"Play in my voice\" : \"Listen to the rewrite\");\n  }\n\n  async function playFeedback() {\n    const audioUrl = state.latestFeedback?.audio;\n    if (!audioUrl) return;\n    if (state.currentAudio) state.currentAudio.pause();\n    state.currentAudio = new Audio(audioUrl);\n    try { await state.currentAudio.play(); } catch {}\n  }\n\n  async function destroyCall() {\n    clearTimeout(state.joinTimeout);\n    state.joinTimeout = null;\n    if (!state.call) return;\n    const call = state.call;\n    state.call = null;\n    try { await call.leave(); } catch {}\n    try { await call.destroy(); } catch {}\n  }\n\n  async function cleanupRemoteRoom() {\n    const conversationId = state.conversationId;\n    await destroyCall();\n    if (!conversationId) return;\n    try {\n      await fetchJSON(`/api/tavus/conversations/${encodeURIComponent(conversationId)}/end`, { method: \"POST\", body: \"{}\" });\n    } catch {}\n    sessionStorage.removeItem(\"fluent-me:active-conversation\");\n    state.conversationId = null;\n  }\n\n  async function endLiveSession() {\n    if (state.ending) return;\n    state.ending = true;\n    stopTimer();\n    setSessionState(\"ending\", \"Saving what you practiced\");\n    const conversationId = state.conversationId;\n    await destroyCall();\n    let report = null;\n    if (conversationId) {\n      try {\n        report = await fetchJSON(`/api/tavus/conversations/${encodeURIComponent(conversationId)}/end`, { method: \"POST\", body: \"{}\" });\n      } catch {}\n    }\n    sessionStorage.removeItem(\"fluent-me:active-conversation\");\n    state.conversationId = null;\n    state.ending = false;\n    renderReview(state.attempts.at(-1), \"You kept the conversation moving and saved a useful correction.\", report);\n    if (conversationId && report?.status !== \"ready\") pollLiveReport(conversationId, 0);\n  }\n\n  async function pollLiveReport(conversationId, attempt) {\n    if (attempt >= 7 || document.body.dataset.screen !== \"review\") return;\n    await new Promise(resolve => setTimeout(resolve, 1000 + attempt * 700));\n    try {\n      const report = await fetchJSON(`/api/tavus/conversations/${encodeURIComponent(conversationId)}/report`, { headers: {} });\n      if (report.summary) setText(\"review-lede\", report.summary);\n      if (report.best_moment) setText(\"review-target\", report.best_moment);\n      if (report.status !== \"ready\") pollLiveReport(conversationId, attempt + 1);\n    } catch {}\n  }\n\n  function endSession() {\n    if (state.capability === \"tavus\" && state.conversationId) endLiveSession();\n    else finishBrowserSession();\n  }\n\n  function drawIdleWave() {\n    cancelAnimationFrame(state.drawFrame);\n    const canvas = $(\"voice-canvas\");\n    if (!canvas || canvas.hidden) return;\n    const context = canvas.getContext(\"2d\");\n    const width = canvas.width;\n    const height = canvas.height;\n    context.clearRect(0, 0, width, height);\n    const gradient = context.createLinearGradient(0, 0, width, 0);\n    gradient.addColorStop(0, \"rgba(128,108,255,.08)\");\n    gradient.addColorStop(.5, \"rgba(154,140,255,.52)\");\n    gradient.addColorStop(1, \"rgba(64,217,173,.08)\");\n    context.strokeStyle = gradient;\n    context.lineWidth = 3;\n    context.beginPath();\n    for (let x = 0; x <= width; x += 6) {\n      const envelope = Math.sin(Math.PI * x / width);\n      const y = height / 2 + Math.sin(x / 30) * 7 * envelope + Math.sin(x / 73) * 4 * envelope;\n      if (x === 0) context.moveTo(x, y); else context.lineTo(x, y);\n    }\n    context.stroke();\n  }\n\n  async function startLiveWave() {\n    if (!state.mediaStream) return;\n    const AudioContext = window.AudioContext || window.webkitAudioContext;\n    if (!AudioContext) return;\n    state.audioContext = new AudioContext();\n    state.analyser = state.audioContext.createAnalyser();\n    state.analyser.fftSize = 256;\n    state.audioContext.createMediaStreamSource(state.mediaStream).connect(state.analyser);\n    const values = new Uint8Array(state.analyser.frequencyBinCount);\n    const canvas = $(\"voice-canvas\");\n    const context = canvas.getContext(\"2d\");\n    const draw = () => {\n      if (!state.analyser || state.sessionState !== \"recording\") return;\n      state.analyser.getByteFrequencyData(values);\n      context.clearRect(0, 0, canvas.width, canvas.height);\n      const bars = 64;\n      const gap = 7;\n      const barWidth = (canvas.width - gap * (bars - 1)) / bars;\n      const gradient = context.createLinearGradient(0, 0, canvas.width, 0);\n      gradient.addColorStop(0, \"#5f51c8\");\n      gradient.addColorStop(.55, \"#9a8cff\");\n      gradient.addColorStop(1, \"#40d9ad\");\n      context.fillStyle = gradient;\n      for (let index = 0; index < bars; index += 1) {\n        const source = values[Math.floor(index / bars * values.length)] / 255;\n        const height = Math.max(5, source * canvas.height * .72);\n        const x = index * (barWidth + gap);\n        context.beginPath();\n        context.roundRect(x, (canvas.height - height) / 2, barWidth, height, barWidth / 2);\n        context.fill();\n      }\n      state.drawFrame = requestAnimationFrame(draw);\n    };\n    draw();\n  }\n\n  function togglePanel(button) {\n    if (button.disabled) return;\n    document.querySelectorAll(\".panel-tab\").forEach(tab => {\n      const active = tab === button;\n      tab.classList.toggle(\"active\", active);\n      tab.setAttribute(\"aria-selected\", String(active));\n    });\n    $(\"coaching-panel\").hidden = button.dataset.panel !== \"coaching\";\n    $(\"perception-panel\").hidden = button.dataset.panel !== \"perception\";\n  }\n\n  async function toggleMic() {\n    if (!state.call) return;\n    const next = !$(\"mic-toggle\").classList.contains(\"off\");\n    await state.call.setLocalAudio(!next);\n    $(\"mic-toggle\").classList.toggle(\"off\", next);\n    setText(\"mic-toggle\", next ? \"Mic off\" : \"Mic\");\n  }\n\n  async function toggleCamera() {\n    if (!state.call) return;\n    const next = !$(\"camera-toggle\").classList.contains(\"off\");\n    await state.call.setLocalVideo(!next);\n    $(\"camera-toggle\").classList.toggle(\"off\", next);\n    setText(\"camera-toggle\", next ? \"Camera off\" : \"Camera\");\n  }\n\n  document.querySelectorAll(\".prompt-chip\").forEach(button => button.addEventListener(\"click\", () => selectPrompt(button)));\n  document.querySelectorAll(\".panel-tab\").forEach(button => button.addEventListener(\"click\", () => togglePanel(button)));\n  $(\"practice-goal\").addEventListener(\"input\", () => document.querySelectorAll(\".prompt-chip\").forEach(chip => chip.classList.remove(\"selected\")));\n  $(\"start-button\").addEventListener(\"click\", startPractice);\n  $(\"record-control\").addEventListener(\"click\", handleRecordControl);\n  $(\"end-session\").addEventListener(\"click\", endSession);\n  $(\"practice-again\").addEventListener(\"click\", () => {\n    $(\"practice-goal\").value = state.goal;\n    startPractice();\n  });\n  $(\"new-goal\").addEventListener(\"click\", () => resetToSetup());\n  $(\"listen-button\").addEventListener(\"click\", playFeedback);\n  $(\"mic-toggle\").addEventListener(\"click\", toggleMic);\n  $(\"camera-toggle\").addEventListener(\"click\", toggleCamera);\n  $(\"transcript-toggle\").addEventListener(\"click\", () => {\n    state.captionsVisible = !state.captionsVisible;\n    $(\"live-words\").hidden = !state.captionsVisible;\n    if (!state.captionsVisible) $(\"caption-strip\").hidden = true;\n    $(\"transcript-toggle\").classList.toggle(\"off\", !state.captionsVisible);\n  });\n\n  window.addEventListener(\"resize\", () => { if (state.sessionState !== \"recording\") drawIdleWave(); });\n  window.addEventListener(\"pagehide\", () => {\n    stopRecognitionAndMedia();\n    if (state.call) { try { state.call.leave(); } catch {} }\n    if (state.conversationId) {\n      fetch(`/api/tavus/conversations/${encodeURIComponent(state.conversationId)}/end`, {\n        method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: \"{}\", keepalive: true,\n      }).catch(() => {});\n    }\n  });\n\n  boot();\n})();\n";
const OG_BASE64 = "";

const json = (value, status = 200) => new Response(JSON.stringify(value), {
  status,
  headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" },
});

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/" || url.pathname === "/index.html") {
      return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
    }
    if (url.pathname === "/static/live.css") {
      return new Response(CSS, { headers: { "content-type": "text/css; charset=utf-8", "cache-control": "public, max-age=3600" } });
    }
    if (url.pathname === "/static/live.js") {
      return new Response(JS, { headers: { "content-type": "text/javascript; charset=utf-8", "cache-control": "public, max-age=3600" } });
    }
    if (url.pathname === "/static/og-v2.png") {
      const raw = atob(OG_BASE64);
      const bytes = new Uint8Array(raw.length);
      for (let i = 0; i < raw.length; i += 1) bytes[i] = raw.charCodeAt(i);
      return new Response(bytes, { headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" } });
    }
    if (url.pathname === "/api/tavus/status") {
      return json({
        configured: false,
        mode: "browser_practice",
        experience_mode: "browser_practice",
        pal_ready: false,
        mirror_voice_ready: false,
        capabilities: { face: "Phoenix", perception: "Raven-1", turn_taking: "Sparrow-1", emotion_recognition: "limited_on_managed_pal" },
      });
    }
    if (url.pathname === "/api/cards") {
      return json({ now: Math.floor(Date.now() / 1000), cards: [] });
    }
    if (url.pathname.startsWith("/api/tavus/conversations")) {
      return json({ error: "Live video is not configured in this environment.", reason: "not_configured" }, 503);
    }
    return new Response("Not found", { status: 404 });
  },
};
